    AdBreak.add_member(:message_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MessageType, location_name: 'MessageType', traits: {"smithy.api#documentation" => "<p>The SCTE-35 ad insertion type. Accepted value: <code>SPLICE_INSERT</code>, <code>TIME_SIGNAL</code>.</p>"}))
    AdBreak.add_member(:offset_millis, Smithy::Schema::Shapes::ShapeRef.new(shape: Long, location_name: 'OffsetMillis', traits: {"smithy.api#default" => 0, "smithy.api#documentation" => "<p>How long (in milliseconds) after the beginning of the program that an ad starts. This value must fall within 100ms of a segment boundary, otherwise the ad break will be skipped.</p>", "smithy.api#required" => {}}))
