    AdBreak.add_member(:splice_insert_message, Smithy::Schema::Shapes::ShapeRef.new(shape: SpliceInsertMessage, location_name: 'SpliceInsertMessage', traits: {"smithy.api#documentation" => "<p>This defines the SCTE-35 <code>splice_insert()</code> message inserted around the ad. For information about using <code>splice_insert()</code>, see the SCTE-35 specficiaiton, section 9.7.3.1.</p>"}))
    AdBreak.add_member(:time_signal_message, Smithy::Schema::Shapes::ShapeRef.new(shape: TimeSignalMessage, location_name: 'TimeSignalMessage', traits: {"smithy.api#documentation" => "<p>Defines the SCTE-35 <code>time_signal</code> message inserted around the ad.</p> <p>Programs on a channel's schedule can be configured with one or more ad breaks. You can attach a <code>splice_insert</code> SCTE-35 message to the ad break. This message provides basic metadata about the ad break.</p> <p>See section 9.7.4 of the 2022 SCTE-35 specification for more information.</p>"}))
    AdBreak.add_member(:ad_break_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: AdBreakMetadataList, location_name: 'AdBreakMetadata', traits: {"smithy.api#documentation" => "<p>Defines a list of key/value pairs that MediaTailor generates within the <code>EXT-X-ASSET</code>tag for <code>SCTE35_ENHANCED</code> output.</p>"}))
