    CdnConfiguration.add_member(:ad_segment_url_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AdSegmentUrlPrefix', traits: {"smithy.api#documentation" => "<p>A non-default content delivery network (CDN) to serve ad segments. By default, AWS Elemental MediaTailor uses Amazon CloudFront with default cache settings as its CDN for ad segments. To set up an alternate CDN, create a rule in your CDN for the origin ads.mediatailor.<i>&lt;region&gt;</i>.amazonaws.com. Then specify the rule's name in this <code>AdSegmentUrlPrefix</code>. When AWS Elemental MediaTailor serves a manifest, it reports your CDN as the source for ad segments.</p>"}))
