    PlaybackConfiguration.add_member(:insertion_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: InsertionMode, location_name: 'InsertionMode', traits: {"smithy.api#default" => "STITCHED_ONLY", "smithy.api#documentation" => "<p>The setting that controls whether players can use stitched or guided ad insertion. The default, <code>STITCHED_ONLY</code>, forces all player sessions to use stitched (server-side) ad insertion. Choosing <code>PLAYER_SELECT</code> allows players to select either stitched or guided ad insertion at session-initialization time. The default for players that do not specify an insertion mode is stitched.</p>"}))
