    PlaybackConfiguration.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The identifier for the playback configuration.</p>"}))
    PlaybackConfiguration.add_member(:personalization_threshold_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'PersonalizationThresholdSeconds', traits: {"smithy.api#documentation" => "<p>Defines the maximum duration of underfilled ad time (in seconds) allowed in an ad break. If the duration of underfilled ad time exceeds the personalization threshold, then the personalization of the ad break is abandoned and the underlying content is shown. This feature applies to <i>ad replacement</i> in live and VOD streams, rather than ad insertion, because it relies on an underlying content stream. For more information about ad break behavior, including ad replacement and insertion, see <a href=\"https://docs.aws.amazon.com/mediatailor/latest/ug/ad-behavior.html\">Ad Behavior in AWS Elemental MediaTailor</a>.</p>"}))
