    PlaybackConfiguration.add_member(:playback_endpoint_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PlaybackEndpointPrefix', traits: {"smithy.api#documentation" => "<p>The URL that the player accesses to get a manifest from AWS Elemental MediaTailor.</p>"}))
    PlaybackConfiguration.add_member(:session_initialization_endpoint_prefix, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SessionInitializationEndpointPrefix', traits: {"smithy.api#documentation" => "<p>The URL that the player uses to initialize a session that uses client-side reporting.</p>"}))
    PlaybackConfiguration.add_member(:slate_ad_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SlateAdUrl', traits: {"smithy.api#documentation" => "<p>The URL for a video asset to transcode and use to fill in time that's not used by ads. AWS Elemental MediaTailor shows the slate to fill in gaps in media content. Configuring the slate is optional for non-VPAID playback configurations. For VPAID, the slate is required because MediaTailor provides it in the slots designated for dynamic ad content. The slate must be a high-quality asset that contains both audio and video.</p>"}))
    PlaybackConfiguration.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: MapofString, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to assign to the playback configuration. Tags are key-value pairs that you can associate with Amazon resources to help with organization, access control, and cost tracking. For more information, see <a href=\"https://docs.aws.amazon.com/mediatailor/latest/ug/tagging.html\">Tagging AWS Elemental MediaTailor Resources</a>.</p>", "smithy.api#jsonName" => "tags"}))
