    PrefetchConsumption.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The time when MediaTailor no longer considers the prefetched ads for use in an ad break. MediaTailor automatically deletes prefetch schedules no less than seven days after the end time. If you'd like to manually delete the prefetch schedule, you can call <code>DeletePrefetchSchedule</code>.</p>", "smithy.api#required" => {}}))
    PrefetchConsumption.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The time when prefetched ads are considered for use in an ad break. If you don't specify <code>StartTime</code>, the prefetched ads are available after MediaTailor retrieves them from the ad decision server.</p>"}))
    PrefetchConsumption.type = Types::PrefetchConsumption
    PrefetchRetrieval.add_member(:dynamic_variables, Smithy::Schema::Shapes::ShapeRef.new(shape: MapofString, location_name: 'DynamicVariables', traits: {"smithy.api#documentation" => "<p>The dynamic variables to use for substitution during prefetch requests to the ad decision server (ADS).</p> <p>You initially configure <a href=\"https://docs.aws.amazon.com/mediatailor/latest/ug/variables.html\">dynamic variables</a> for the ADS URL when you set up your playback configuration. When you specify <code>DynamicVariables</code> for prefetch retrieval, MediaTailor includes the dynamic variables in the request to the ADS.</p>"}))
    PrefetchRetrieval.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Timestampunix, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The time when prefetch retrieval ends for the ad break. Prefetching will be attempted for manifest requests that occur at or before this time.</p>", "smithy.api#required" => {}}))
