    PrefetchRetrieval.add_member(:traffic_shaping_type, Smithy::Schema::Shapes::ShapeRef.new(shape: TrafficShapingType, location_name: 'TrafficShapingType', traits: {"smithy.api#documentation" => "<p>Indicates if this configuration uses a retrieval window for traffic shaping and limiting the number of requests to the ADS at one time.</p>"}))
