    PrefetchSchedule.add_member(:consumption, Smithy::Schema::Shapes::ShapeRef.new(shape: PrefetchConsumption, location_name: 'Consumption', traits: {"smithy.api#documentation" => "<p>Consumption settings determine how, and when, MediaTailor places the prefetched ads into ad breaks for single prefetch schedules. Ad consumption occurs within a span of time that you define, called a <i>consumption window</i>. You can designate which ad breaks that MediaTailor fills with prefetch ads by setting avail matching criteria.</p>"}))
