    PrefetchSchedule.add_member(:schedule_type, Smithy::Schema::Shapes::ShapeRef.new(shape: PrefetchScheduleType, location_name: 'ScheduleType', traits: {"smithy.api#documentation" => "<p>The frequency that MediaTailor creates prefetch schedules. <code>SINGLE</code> indicates that this schedule applies to one ad break. <code>RECURRING</code> indicates that MediaTailor automatically creates a schedule for each ad avail in a live event.</p> <p>For more information about the prefetch types and when you might use each, see <a href=\"https://docs.aws.amazon.com/mediatailor/latest/ug/prefetching-ads.html\">Prefetching ads in Elemental MediaTailor.</a> </p>"}))
